import h5py,numpy as np
from pathlib import Path
starts=[]; ends=[]; missing=[]; multi=[]
for p in sorted(Path('/app/data').glob('sub-*/*.nwb')):
 with h5py.File(p,'r') as f:
  b=f['processing/behavior/BehavioralTimeSeries']; tr=b['trial number/data'][:]; pos=b['position/data'][:]; rz=b['reward_zone/data'][:]
  for t in np.unique(tr[tr>=0]).astype(int):
   ix=np.where(tr==t)[0]; dr=np.diff(rz[ix],prepend=rz[ix[0]])
   ev=np.where(dr>0)[0]
   if len(ev):
    starts.append(pos[ix[ev[0]]]); ends.append(pos[ix[ev[-1]]]);
    if len(ev)>1: multi.append(len(ev))
   else: missing.append((p.name,t))
print('trials with entry',len(starts),'missing',len(missing),'examples',missing[:10])
for a in [np.array(starts),np.array(ends)]: print('quantiles',np.quantile(a,[0,.01,.1,.25,.5,.75,.9,.99,1]))
print('start nearest centers counts',np.bincount(np.argmin(abs(np.array(starts)[:,None]-np.array([80,200,320])),axis=1),minlength=3))
print('increments/trial median,max',np.median(multi),max(multi))
